steps.run:
New-Item -ItemType Directory -Force -Path tmp/nk4-ci | Out-Null
function Get-Inventory([string]$ClassName, [string[]]$Properties) {
  try {
    $items = @(Get-CimInstance -ClassName $ClassName -OperationTimeoutSec 20 -ErrorAction Stop |
      Select-Object -First 32 -Property $Properties)
    return @{ status = 'available'; items = $items }
  } catch {
    return @{ status = 'error'; error = $_.Exception.Message }
  }
}
$inventory = [ordered]@{
  captured_utc = [DateTime]::UtcNow.ToString('o')
  system = Get-Inventory 'Win32_ComputerSystem' @('Manufacturer', 'Model', 'NumberOfLogicalProcessors', 'TotalPhysicalMemory')
  os = Get-Inventory 'Win32_OperatingSystem' @('Caption', 'Version', 'BuildNumber', 'OSArchitecture')
  cpu = Get-Inventory 'Win32_Processor' @('Name', 'NumberOfCores', 'NumberOfLogicalProcessors')
  gpu = Get-Inventory 'Win32_VideoController' @('Name', 'VideoProcessor', 'DriverVersion', 'AdapterRAM')
}
$inventory | ConvertTo-Json -Depth 5 | Set-Content -Encoding utf8 tmp/nk4-ci/host-inventory.json

$vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe'
$installation = & $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
if (-not $installation) {
  throw 'The pinned MSVC C++ toolchain is not installed on this runner.'
}
$devcmd = Join-Path $installation 'Common7\Tools\VsDevCmd.bat'
if (-not (Test-Path -LiteralPath $devcmd -PathType Leaf)) {
  throw "Visual Studio developer command file was not found: $devcmd"
}
# Runner image updates move the default MSVC (20261111 ships 14.52). Select the locked
# toolset explicitly and add it side by side when the image lacks it; build.py still
# refuses any other VCToolsVersion.
$lock = Get-Content -Raw -LiteralPath 'research/rc-monster-truck/native/toolchain-lock.json' | ConvertFrom-Json
$toolset = $lock.windows.compiler_toolset
$toolsetRoot = Join-Path $installation 'VC\Tools\MSVC'
if (-not (Test-Path -LiteralPath (Join-Path $toolsetRoot $toolset) -PathType Container)) {
  function Show-InstallerLog {
    Get-ChildItem -LiteralPath $env:TEMP -Filter 'dd_*.log' -ErrorAction SilentlyContinue |
      Sort-Object LastWriteTime | Select-Object -Last 2 |
      ForEach-Object { Write-Host "== $($_.FullName)"; Get-Content -LiteralPath $_.FullName -Tail 40 }
  }
  # Take the component id from this instance's catalog: superseded toolsets can gain a VS
  # version suffix (VC.14.44.17.14.x86.x64). Prefer the bare id when the catalog has it.
  $minor = ($toolset -split '\.')[0..1] -join '.'
  $bare = "Microsoft.VisualStudio.Component.VC.$minor.x86.x64"
  $instanceId = & $vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property instanceId
  $catalog = Join-Path $env:ProgramData "Microsoft\VisualStudio\Packages\_Instances\$instanceId\catalog.json"
  $ids = @()
  if (Test-Path -LiteralPath $catalog -PathType Leaf) {
    $pattern = '"(Microsoft\.VisualStudio\.Component\.VC\.' + [regex]::Escape($minor) + '(?:\.\d+\.\d+)?\.x86\.x64)"'
    $ids = @([regex]::Matches((Get-Content -Raw -LiteralPath $catalog), $pattern) |
      ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique)
  }
  $component = if ($ids.Count -eq 0 -or $ids -contains $bare) { $bare } else { $ids[-1] }
  Write-Host "MSVC $toolset is absent (found: $((Get-ChildItem -LiteralPath $toolsetRoot -Name) -join ', ')); catalog offers: $($ids -join ', '); adding $component."
  $installer = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vs_installer.exe'
  $arguments = "modify --installPath `"$installation`" --add $component --quiet --norestart --nocache"
  $started = Get-Date
  $process = Start-Process -FilePath $installer -ArgumentList $arguments -Wait -PassThru -WindowStyle Hidden
  Get-Process -Name setup, vs_installer, vs_installershell -ErrorAction SilentlyContinue |
    Wait-Process -Timeout 900 -ErrorAction SilentlyContinue
  Write-Host "Visual Studio Installer exited $($process.ExitCode) after $([int]((Get-Date) - $started).TotalSeconds) s."
  if ($process.ExitCode -notin 0, 3010) {
    Show-InstallerLog
    throw "Visual Studio Installer could not add $component (exit $($process.ExitCode))."
  }
  if (-not (Test-Path -LiteralPath (Join-Path $toolsetRoot $toolset) -PathType Container)) {
    Show-InstallerLog
    throw "$component did not provide MSVC $toolset (found: $((Get-ChildItem -LiteralPath $toolsetRoot -Name) -join ', ')). Changing the lock is a deliberate rebuild for its owning track."
  }
}
$command = "call `"$devcmd`" -no_logo -arch=amd64 -host_arch=amd64 -vcvars_ver=$toolset >nul && set"
$developerEnvironment = & $env:ComSpec /d /s /c $command
if ($LASTEXITCODE -ne 0) {
  throw 'Could not initialize the x64 Visual Studio developer environment.'
}
foreach ($entry in $developerEnvironment) {
  $separator = $entry.IndexOf('=')
  if ($separator -gt 0) {
    $name = $entry.Substring(0, $separator)
    $value = $entry.Substring($separator + 1)
    Set-Item -Path "Env:$name" -Value $value
  }
}
where.exe cl.exe
if ($LASTEXITCODE -ne 0) {
  throw 'MSVC cl.exe was not available after initializing the developer environment.'
}
python research/rc-monster-truck/native/build.py --jobs 2 --godot "$env:GODOT_WINDOWS_EXE"
if ($LASTEXITCODE -ne 0) {
  exit $LASTEXITCODE
}

set -euo pipefail
shopt -s nullglob
archives=(tmp/nk4-package/dist/openrc-simulator-*-windows-x86_64.zip)
[ "${#archives[@]}" -eq 1 ] || { echo "expected exactly one Windows release archive" >&2; exit 1; }
checksum="$(grep -E '^[0-9a-f]{64}  openrc-simulator-[^/ ]+-windows-x86_64\.zip$' tmp/nk4-package/dist/SHA256SUMS)" ||
  { echo "SHA256SUMS lists no Windows release archive" >&2; exit 1; }
[ "$(printf '%s\n' "$checksum" | wc -l)" -eq 1 ] || { echo "SHA256SUMS lists several Windows archives" >&2; exit 1; }
(cd tmp/nk4-package/dist && printf '%s\n' "$checksum" | sha256sum --check --strict -)
python -m zipfile -e "${archives[0]}" tmp/nk4-package/app
for file in "OpenRC Simulator.exe" native/kernel/openrc_native_kernel.dll \
    native/kernel/openrc_native_kernel.gdextension native/kernel/package-receipt.json; do
  test -s "tmp/nk4-package/app/$file" || { echo "Windows archive lacks $file" >&2; exit 1; }
done

python -m unittest discover -s tools/godot -p 'test_resource_runner.py' 2>&1 | Tee-Object resource-windows.log
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python -m unittest discover -s research/performance -p 'test_session_baseline.py' 2>&1 | Tee-Object performance-windows.log
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python -m unittest discover -s tools/godtest -p 'test_*.py' 2>&1 | Tee-Object godtest-windows.log
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }

